using UnityEngine;

public class DemonLordSummon : MonoBehaviour
{
    public GameObject demonLordPrefab;

    public void SummonDemonLord(GameObject from, GameObject to)
    {
        GameObject demonLord = Instantiate(demonLordPrefab, from.transform.position, Quaternion.identity);
        demonLord.GetComponent<Stats>().Initialize(); // Assuming demon lord has an Initialize method
        from.GetComponent<Stats>().takeDamage(10); // 10 self damage for summoning
        Debug.Log(from.name + " summoned a demon lord!");
    }
}
